enc_flag = b'enL\xcc\xbfx\xc8\x11\xe5(\x18\xe6\xc2\xe5\x14\xb7\xd4\xd7c\x8b)~_\xe0\xe5\x91jm\x99\xfbx\xa8H\xfa\xb7.\xaf\x97\xc8\xbe\xbaHX\x96\x1cV&\xe2\xdb\x91N\xeb'


import string
from collections import Counter
from math import log
import json
from argparse import ArgumentParser
from urllib.request import urlopen 

def get_ctr(txt, n):
    ctr = Counter("".join(x) for x in zip(*[txt[i:] for i in range(n)]))
    return ctr


def calc_ngram(txt, ns):
    ctrs = [get_ctr(txt, n) for n in ns]
    dt = {}
    for d in ctrs:
        dt |= d
    ln = sum([v for v in dt.values()])
    return {k: log(v / ln) for k, v in dt.items()}

def calc_freq_table(corpus):
    text = ''.join(corpus)
    text = [c for c in text if c in charset]
    ln = len(text)
    freq_tbl = {}
    for t in text:
        freq_tbl[t] = freq_tbl.get(t, 0) + 1
    for k in freq_tbl:
        freq_tbl[k] = freq_tbl[k] / ln 
    return freq_tbl

def calc_score(group, freq_tbl):
    score = 0
    for c in group:
        if c in freq_tbl:
            score += log(freq_tbl[c])
    return score

charset = string.ascii_letters + string.digits + ' ,.\n'  # The characters used in the ciphertext
char_to_int = {c: i for i, c in enumerate(charset)}
n_chars = len(charset)
keylen = 87


text = ''.join(urlopen("http://www.gutenberg.org/cache/epub/84/pg84.txt").read().decode('utf-8', errors='ignore'))
# only keep characters in charset
text = [c for c in text if c in charset]
freq_tbl = calc_freq_table(text) 
print("Frequency table calculated.")
print(json.dumps(freq_tbl, indent=2))

groups = dict()
for i, c in enumerate(ciphertext):
    if i % keylen not in groups:
        groups[i % keylen] = []
    groups[i % keylen].append(c) # Group characters by their position modulo key length

key = [0] * keylen 
for idx in range(len(groups)):
    print(f'Analyzing group {idx} for best shift:')
    best_shift = 0
    best_score = 0
    for i in range(n_chars):
        # shift group[0] by i and calculate n-gram frequencies
        tmp = [charset[(char_to_int[c] + i) % n_chars] for c in groups[idx]]
        # calculate score
        score = calc_score(tmp, freq_tbl)
        # print(f'Shift: {i} -> {''.join(tmp)[:5]}, Score: {score}')
        if i == 0 or score > best_score:
            best_score = score
            best_shift = i
    groups[idx] = [charset[(char_to_int[c] + best_shift) % n_chars] for c in groups[idx]]
    print(f'Best shift for group {idx}: {best_shift} -> {"".join(groups[idx])[:5]}')
    key[idx] = (-best_shift) % n_chars

decoded = []
for i in range(len(ciphertext)):
    decoded.append(groups[i % keylen][i // keylen])
print('Decoded text:')
decoded_text = ''.join(decoded)
print(decoded_text)

# recover key
key = ''.join([charset[k] for k in key])
print(key)

import hashlib
h = hashlib.shake_128(key.encode()).digest(len(enc_flag))
print(bytes(a ^ b for a, b in zip(h, enc_flag)).decode())
